class FloatingLabel{constructor(e,t={}){if(!e)return;this.options={focusClass:"focus",activeClass:"active",errorClass:"error",...t},e.classList.add("has-floated-label");e.querySelectorAll("label").forEach(e=>{const t=e.getAttribute("for"),s=document.getElementById(t);s&&(["keyup","input","change"].forEach(e=>{s.addEventListener(e,()=>{s.parentNode.classList.remove(this.options.errorClass),s.parentNode.classList.toggle(this.options.activeClass,!!s.value)})}),s.addEventListener("focus",()=>{s.parentNode.classList.add(this.options.focusClass)}),s.addEventListener("blur",()=>{s.parentNode.classList.remove(this.options.focusClass)}),s.parentNode.classList.toggle(this.options.activeClass,!!s.value))})}}window.floatingLabel=new FloatingLabel(document.querySelector(".form")),window.addEventListener("load",()=>{"undefined"!=typeof baguetteBox&&baguetteBox.run(".baguetteBoxGallery")});